// inviteTokenFromMail returns the token in the link of the newest email.
func inviteTokenFromMail(t *testing.T, e *apitest.Env) string {
	t.Helper()
	msgs := e.Mail.Messages()
	m := regexp.MustCompile(`token=([^\s]+)`).FindStringSubmatch(msgs[len(msgs)-1].Body)
	if m == nil {
		t.Fatalf("no link in %q", msgs[len(msgs)-1].Body)
	}
	token, _ := url.QueryUnescape(m[1])
	return token
}

func TestInviteTokens(t *testing.T) {
	e := apitest.New(t)
	_, viewerKey := e.AddMember(e.Acme, "viewer@acme.example", store.RoleViewer)

	var first store.Invite
	e.MustDo(http.StatusCreated, "POST", "/v1/invites", e.Acme.Key, map[string]string{"email": "new@people.example", "role": "member"}, &first)
	token := inviteTokenFromMail(t, e)
	if len(token) != 43 {
		t.Fatalf("token %q is not 43 characters", token)
	}
	if r := e.Do("POST", "/v1/invites", e.Acme.Key, map[string]string{"email": "other@people.example", "role": "viewer"}); strings.Contains(r.String(), token) {
		t.Fatalf("the create answer has the token: %s", r)
	}
	var pending struct {
		Items []map[string]any
	}
	r := e.MustDo(http.StatusOK, "GET", "/v1/invites", viewerKey, nil, &pending)
	if strings.Contains(r.Body.String(), token) || strings.Contains(r.Body.String(), "token") {
		t.Fatalf("a viewer reads a token: %s", r.Body)
	}
	if len(pending.Items) != 2 || pending.Items[0]["expires_at"] == nil {
		t.Fatalf("pending invites = %+v", pending.Items)
	}

	// Inviting the same address again, in another case, revokes the first invite: only the newest token works.
	e.MustDo(http.StatusCreated, "POST", "/v1/invites", e.Acme.Key, map[string]string{"email": "NEW@people.example", "role": "admin"}, nil)
	newest := inviteTokenFromMail(t, e)
	if r := e.Do("POST", "/v1/invites/accept", "", map[string]string{"token": token, "name": "New Person"}); r.Code != http.StatusNotFound {
		t.Fatalf("a superseded token: %s", r)
	}
	var pendingAfter struct{ Items []store.Invite }
	e.MustDo(http.StatusOK, "GET", "/v1/invites", e.Acme.Key, nil, &pendingAfter)
	if len(pendingAfter.Items) != 2 {
		t.Fatalf("pending after the new invite = %+v", pendingAfter.Items)
	}

	var accepted struct {
		User store.User `json:"user"`
	}
	e.MustDo(http.StatusCreated, "POST", "/v1/invites/accept", "", map[string]string{"token": newest, "name": "New Person"}, &accepted)
	if accepted.User.Email != "NEW@people.example" && accepted.User.Email != "new@people.example" {
		t.Fatalf("accepted = %+v", accepted)
	}
	if r := e.Do("POST", "/v1/invites/accept", "", map[string]string{"token": newest, "name": "Someone Else"}); r.Code != http.StatusGone || r.Map(t)["error"] != "invite_used" {
		t.Fatalf("a used token: %s", r)
	}

	// An invite is good for 7 days after it was created, and no longer.
	e.MustDo(http.StatusCreated, "POST", "/v1/invites", e.Acme.Key, map[string]string{"email": "late@people.example", "role": "member"}, nil)
	late := inviteTokenFromMail(t, e)
	e.Clock.Advance(7 * 24 * time.Hour)
	var pendingLate struct{ Items []store.Invite }
	e.MustDo(http.StatusOK, "GET", "/v1/invites", e.Acme.Key, nil, &pendingLate)
	if len(pendingLate.Items) != 1 {
		t.Fatalf("a week old invite is not pending: %+v", pendingLate.Items)
	}
	e.Clock.Advance(time.Second)
	if r := e.Do("POST", "/v1/invites/accept", "", map[string]string{"token": late, "name": "Late"}); r.Code != http.StatusGone || r.Map(t)["error"] != "invite_expired" {
		t.Fatalf("an expired token: %s", r)
	}
	var pendingExpired struct{ Items []store.Invite }
	e.MustDo(http.StatusOK, "GET", "/v1/invites", e.Acme.Key, nil, &pendingExpired)
	if len(pendingExpired.Items) != 0 {
		t.Fatalf("expired invites are pending: %+v", pendingExpired.Items)
	}
}

