402		email = strings.TrimSpace(email)
403		if !validEmail(email) {
404			return Invite{}, invalid("an invite needs a valid email address")
405		}
406		if !role.Valid() || role == RoleOwner {
407			return Invite{}, invalid("an invite's role is admin, billing, member or viewer")
408		}
409		s.mu.Lock()
410		defer s.mu.Unlock()
411		if _, ok := s.orgs[orgID]; !ok {
412			return Invite{}, ErrNotFound
413		}
414		if uid, ok := s.usersByEmail[normEmail(email)]; ok {
415			if _, member := s.members[memberKey{orgID, uid}]; member {
416				return Invite{}, ErrAlreadyMember
417			}
418		}
419		t := now.UTC()
420		for id, old := range s.invites {
421			if old.OrgID == orgID && normEmail(old.Email) == normEmail(email) && old.pending(now) {
422				old.RevokedAt = &t
423				s.invites[id] = old
424			}
425		}
426		token, hash := NewInviteToken()
427		inv := Invite{ID: s.newID("inv"), OrgID: orgID, Email: email, Role: role, TokenHash: hash, InvitedBy: invitedBy, CreatedAt: t}
428		s.invites[inv.ID] = inv
429		inv.Token = token
430		return inv, nil
431	}
